/**
 * LearnForge Structured Challenge Parser
 *
 * Robustly parses `forge-challenge` blocks generated by the Socratic AI
 * into structured ForgeChallenge objects to automatically configure the
 * Monaco editor and test runner harness.
 */

import type { ForgeChallenge, ParsedChallengeResult } from './types';

/**
 * Strips outer markdown code block fences (e.g. ```go\n...\n```) from a code snippet
 * if the AI nested them inside a section.
 */
function cleanCodeSnippet(rawCode: string): string {
  let cleaned = rawCode.trim();

  // Strip leading ```lang\n if present
  cleaned = cleaned.replace(/^```[a-zA-Z0-9_-]*\r?\n/, '');
  // Strip trailing \n``` if present
  cleaned = cleaned.replace(/\r?\n```$/, '');
  cleaned = cleaned.trim();

  // Remove leading YAML pipe indicators if present (| or |-)
  if (cleaned.startsWith('|\n') || cleaned.startsWith('| \n')) {
    cleaned = cleaned.substring(cleaned.indexOf('\n') + 1).trim();
  } else if (cleaned.startsWith('|-\n')) {
    cleaned = cleaned.substring(cleaned.indexOf('\n') + 1).trim();
  }

  return cleaned;
}

/**
 * Robustly extracts the forge-challenge block and body from content,
 * properly handling nested code blocks with triple backticks.
 */
function extractChallengeBlock(content: string): { fullBlock: string; body: string } | null {
  if (!content) return null;

  // Find start: ```forge-challenge or ~~~forge-challenge
  const startRegex = /(?:^|\n)(`{3,}|~{3,})forge-challenge[^\r\n]*\r?\n/i;
  const startMatch = startRegex.exec(content);
  if (!startMatch) return null;

  const fenceChars = startMatch[1]; // e.g. "```" or "````"
  const startOffset = startMatch.index + (startMatch[0].startsWith('\n') ? 1 : 0);
  const bodyStartPos = startOffset + startMatch[0].length - (startMatch[0].startsWith('\n') ? 1 : 0);
  const remaining = content.slice(bodyStartPos);

  // If opening fence is 4+ chars, closing fence must have >= same length
  if (fenceChars.length >= 4) {
    const endRegex = new RegExp(`\\r?\\n${fenceChars[0]}{${fenceChars.length},}(?:\\r?\\n|$)`);
    const endMatch = endRegex.exec(remaining);
    if (endMatch) {
      const body = remaining.slice(0, endMatch.index);
      const fullBlock = content.slice(startOffset, bodyStartPos + endMatch.index + endMatch[0].length);
      return { fullBlock, body };
    }
    return { fullBlock: content.slice(startOffset), body: remaining };
  }

  // If opening fence is 3 backticks (```), candidate closing fences may be inner code fences.
  // We scan all closing fences and find the one that actually terminates the challenge.
  const closingRegex = /\r?\n`{3,}(?:\r?\n|$)/g;
  let match: RegExpExecArray | null;
  let chosenEndIndex = -1;
  let chosenMatchLength = 0;

  while ((match = closingRegex.exec(remaining)) !== null) {
    const afterCandidate = remaining.slice(match.index + match[0].length);

    // If candidate is followed immediately by another section header like test_code:,
    // then this candidate was just closing starter_code, NOT the entire challenge!
    if (/^\s*(test[-_]code:|###\s*test|---test|solution[-_]code:|###\s*solution)/i.test(afterCandidate)) {
      continue;
    }

    chosenEndIndex = match.index;
    chosenMatchLength = match[0].length;

    // If immediately followed by another closing fence (e.g. inner ``` then outer ```), continue to pick the outer
    if (/^\s*`{3,}/.test(afterCandidate)) {
      continue;
    }
    break;
  }

  if (chosenEndIndex !== -1) {
    const body = remaining.slice(0, chosenEndIndex);
    const fullBlock = content.slice(startOffset, bodyStartPos + chosenEndIndex + chosenMatchLength);
    return { fullBlock, body };
  }

  // Unclosed block (e.g. streaming active or trailing block)
  return {
    fullBlock: content.slice(startOffset),
    body: remaining,
  };
}

/**
 * Parses the internal body of a `forge-challenge` block into a ForgeChallenge object.
 */
function parseChallengeBody(bodyText: string): ForgeChallenge | null {
  const lines = bodyText.split(/\r?\n/);

  let title = '';
  let language = '';
  let promptAccumulator: string[] = [];
  let starterCodeAccumulator: string[] = [];
  let testCodeAccumulator: string[] = [];
  let solutionCodeAccumulator: string[] = [];

  type Section = 'header' | 'prompt' | 'starter_code' | 'test_code' | 'solution_code';
  let currentSection: Section = 'header';

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmedLine = line.trim();
    const lowerTrimmed = trimmedLine.toLowerCase();

    // Section transitions
    if (
      lowerTrimmed.startsWith('starter_code:') ||
      lowerTrimmed.startsWith('starter-code:') ||
      lowerTrimmed === '---starter_code---' ||
      lowerTrimmed === '### starter code' ||
      lowerTrimmed === '### starter_code'
    ) {
      currentSection = 'starter_code';
      const colonIndex = line.indexOf(':');
      if (colonIndex !== -1 && !lowerTrimmed.startsWith('---') && !lowerTrimmed.startsWith('###')) {
        const afterColon = line.substring(colonIndex + 1).trim();
        if (afterColon && afterColon !== '|' && afterColon !== '|-') {
          starterCodeAccumulator.push(afterColon);
        }
      }
      continue;
    }

    if (
      lowerTrimmed.startsWith('test_code:') ||
      lowerTrimmed.startsWith('test-code:') ||
      lowerTrimmed === '---test_code---' ||
      lowerTrimmed === '### test code' ||
      lowerTrimmed === '### test_code'
    ) {
      currentSection = 'test_code';
      const colonIndex = line.indexOf(':');
      if (colonIndex !== -1 && !lowerTrimmed.startsWith('---') && !lowerTrimmed.startsWith('###')) {
        const afterColon = line.substring(colonIndex + 1).trim();
        if (afterColon && afterColon !== '|' && afterColon !== '|-') {
          testCodeAccumulator.push(afterColon);
        }
      }
      continue;
    }

    if (
      lowerTrimmed.startsWith('solution_code:') ||
      lowerTrimmed.startsWith('solution-code:') ||
      lowerTrimmed === '---solution_code---' ||
      lowerTrimmed === '### solution code' ||
      lowerTrimmed === '### solution_code'
    ) {
      currentSection = 'solution_code';
      const colonIndex = line.indexOf(':');
      if (colonIndex !== -1 && !lowerTrimmed.startsWith('---') && !lowerTrimmed.startsWith('###')) {
        const afterColon = line.substring(colonIndex + 1).trim();
        if (afterColon && afterColon !== '|' && afterColon !== '|-') {
          solutionCodeAccumulator.push(afterColon);
        }
      }
      continue;
    }

    if (lowerTrimmed.startsWith('prompt:')) {
      currentSection = 'prompt';
      const colonIndex = line.indexOf(':');
      const afterColon = line.substring(colonIndex + 1).trim();
      if (afterColon && afterColon !== '|' && afterColon !== '|-') {
        promptAccumulator.push(afterColon);
      }
      continue;
    }

    // Header fields
    if (currentSection === 'header') {
      if (lowerTrimmed.startsWith('title:')) {
        title = line.substring(line.indexOf(':') + 1).trim();
        continue;
      }
      if (lowerTrimmed.startsWith('language:')) {
        language = line.substring(line.indexOf(':') + 1).trim().toLowerCase();
        continue;
      }
    }

    // Accumulate according to current section
    switch (currentSection) {
      case 'prompt':
        promptAccumulator.push(line);
        break;
      case 'starter_code':
        starterCodeAccumulator.push(line);
        break;
      case 'test_code':
        testCodeAccumulator.push(line);
        break;
      case 'solution_code':
        solutionCodeAccumulator.push(line);
        break;
      case 'header':
        if (trimmedLine.length > 0 && title) {
          promptAccumulator.push(line);
        }
        break;
    }
  }

  const prompt = promptAccumulator.join('\n').trim();
  const starterCode = cleanCodeSnippet(starterCodeAccumulator.join('\n'));
  const testCode = cleanCodeSnippet(testCodeAccumulator.join('\n'));
  const solutionCode = solutionCodeAccumulator.length > 0
    ? cleanCodeSnippet(solutionCodeAccumulator.join('\n'))
    : undefined;

  if (!title && !prompt && !starterCode) {
    return null;
  }

  return {
    title: title || 'Milestone Challenge',
    language: language || 'go',
    prompt: prompt || 'Complete the implementation according to the milestone requirements.',
    starter_code: starterCode,
    test_code: testCode,
    solution_code: solutionCode,
  };
}

/**
 * Extracts a structured ForgeChallenge from full AI response text if present.
 * Returns null if no `forge-challenge` block exists in the response.
 */
export function parseChallengeFromResponse(content: string): ForgeChallenge | null {
  const extracted = extractChallengeBlock(content);
  if (!extracted) return null;
  return parseChallengeBody(extracted.body);
}

/**
 * Parses response text and separates the conversational tutor message from the
 * structured challenge block, enabling clean dual-pane rendering.
 */
export function extractCleanResponse(content: string): ParsedChallengeResult {
  const extracted = extractChallengeBlock(content);
  if (!extracted) {
    return {
      challenge: null,
      conversationalText: (content || '').trim(),
      hasChallenge: false,
    };
  }

  const challenge = parseChallengeBody(extracted.body);
  const conversationalText = content.replace(extracted.fullBlock, '').trim();

  return {
    challenge,
    conversationalText,
    hasChallenge: challenge !== null,
    rawChallengeBlock: extracted.fullBlock,
  };
}
